    <div class="kanban-board">
        @for (int i = 0; i < columns.Length; i++)
        {
            var index = i;
            var column = columns[index];
            var columnTasks = GetFilteredTasksForColumn(column);
            <KanbanColumn ColumnName="@column"
                          Tasks="columnTasks"
